package com.drogaria.backend.controller;
import com.drogaria.backend.dto.PagamentoResponse; import com.drogaria.backend.service.PagamentoService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/pagamento") public class PagamentoController { private final PagamentoService s; public PagamentoController(PagamentoService s){this.s=s;} @GetMapping("/{id}") public PagamentoResponse buscar(@PathVariable Integer id){return s.buscar(id);} @GetMapping("/pedido/{idPedido}") public PagamentoResponse pedido(@PathVariable Integer idPedido){return s.pedido(idPedido);} @PutMapping("/{id}/status") public PagamentoResponse status(@PathVariable Integer id,@RequestParam String valor){return s.status(id,valor);} }